/* From Uiverse.io by Yaya12085 - Tags: subscription, card, price, plan */
.__UIV_SCOPE__ .pack-container {
  position: relative;
  display: flex;
  max-width: 350px;
  flex-direction: column;
  border-radius: 12px;
  background-color: #212121;
  border: 1px solid #fff;
  padding: 1.6rem;
  color: #fff;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

.__UIV_SCOPE__ .header {
  position: relative;
  margin: 0;
  margin-bottom: 2rem;
  overflow: hidden;
  border-radius: 0;
  border-bottom: 1px solid #fff;
  background: transparent;
  padding-bottom: 1rem;
  text-align: center;
}

.__UIV_SCOPE__ .title {
  display: block;
  font-family: sans-serif;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-transform: uppercase;
  color: #fff
}

.__UIV_SCOPE__ .price-container {
  margin-top: 10px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: 4px;
  font-family: sans-serif;
  font-size: 4.5rem;
  line-height: 1;
}

.__UIV_SCOPE__ .price-container span:first-child {
  margin-top: 10px;
  font-size: 2.25rem;
  line-height: 2.5rem;
}

.__UIV_SCOPE__ .price-container span:last-child {
  align-self: flex-end;
  font-size: 2.25rem;
  line-height: 2.5rem;
}

.__UIV_SCOPE__ .lists {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.__UIV_SCOPE__ .list {
  display: flex;
  align-items: center;
  gap: 10px;
}

.__UIV_SCOPE__ .list span {
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background-color: rgba(255, 255, 255, 0.185);
  height: 30px;
  width: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .list span svg {
  height: 12px;
  width: 12px;
}

.__UIV_SCOPE__ .list p {
  display: block;
  font-family: sans-serif;
}

.__UIV_SCOPE__ .button-container {
  margin-top: 20px;
  padding: 0;
}

.__UIV_SCOPE__ .button-container button {
  display: block;
  width: 100%;
  background-color: #fff;
  padding: 10px 20px;
  text-transform: uppercase;
  color: #000;
  outline: 0;
  border: 0;
  border-radius: 10px;
}
